/**
 * Cross-platform OS-level per-process TCP traffic monitor & daily archive
 * for agy-ledger.
 *
 * Tracks outbound & local-proxy TCP traffic generated by Antigravity processes
 * (`Antigravity`, `language_server*`, `agy-cli`) while automatically excluding
 * internal Antigravity loopback IPC and unrelated local dev servers:
 *
 *   - Windows defaults to the local Clash-compatible proxy connection API.
 *     The optional TCP EStats collector uses a PowerShell + compiled C# worker
 *     (`win_tcp_monitor.ps1`) calling `iphlpapi.dll` (`GetExtendedTcpTable` +
 *     `GetPerTcpConnectionEStats` / `GetPerTcp6ConnectionEStats`). Requires
 *     Administrator privileges on Windows; degrades cleanly to `admin_required`
 *     when unprivileged.
 *   - macOS (`darwin`): built-in `/usr/bin/nettop` + `lsof` (no root required).
 *   - Linux (`linux`): built-in `ss -tinpH` + `ss -tlpnH` (no root required).
 *
 * Persists daily & hourly upload/download bytes to `traffic-archive.json`
 * inside the plugin state directory.
 */
import { execFile, spawn } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const __dirname = dirname(fileURLToPath(import.meta.url));
const WIN_MONITOR_SCRIPT = join(__dirname, 'win_tcp_monitor.ps1');
const execFileAsync = promisify(execFile);

const FLUSH_INTERVAL_MS = 10_000;
const MAX_SINGLE_TICK_BYTES = 1024 * 1024 * 1024; // 1 GiB sanity guard per tick (~5.4 Gbps at 1.5s)
const WIN_POLL_MS = 1500;
const PROXY_POLL_MS = 1000;
const LOCAL_CONTROLLER_PORTS = [10813, 9090, 9097];
const MAC_POLL_MS = 3000;
const LINUX_POLL_MS = 2500;

const PROXY_PROCESS_TOKENS = [
  'mihomo',
  'clash',
  'sing-box',
  'sing_box',
  'v2ray',
  'xray',
  'hysteria',
  'tuic',
  'naive',
  'ss-local',
  'sslocal',
  'shadowsocks',
  'trojan',
  'privoxy',
  'polipo',
  'squid',
  'fiddler',
  'charles',
  'mitmproxy',
  'nekoray',
  'nekobox',
  'flclash',
  'sparkle',
  'surge',
  'karing',
  'qv2ray',
  'gost',
  'brook',
  'tailscaled',
  'warp',
  'proxifier',
  'loon',
  'stash',
  'daed',
  'juicity',
];

export function isAntigravityProcessName(rawName) {
  const name = String(rawName || '')
    .trim()
    .toLowerCase()
    .replace(/\.exe$/i, '');
  if (!name) return false;
  return (
    name === 'antigravity' ||
    name.startsWith('antigravity ') ||
    name.startsWith('antigravity-') ||
    name === 'language_server' ||
    name.startsWith('language_server_') ||
    name.startsWith('language_server-') ||
    name === 'agy-cli'
  );
}

export function isKnownProxyProcessName(rawName) {
  const name = String(rawName || '')
    .trim()
    .toLowerCase()
    .replace(/\.exe$/i, '');
  if (!name) return false;
  return PROXY_PROCESS_TOKENS.some((tok) => name.includes(tok));
}

function isLoopbackHost(host) {
  const h = String(host || '').trim().toLowerCase().replace(/^\[|\]$/g, '');
  return h === '::1' || h === 'localhost' || h.startsWith('127.') || h.startsWith('::ffff:127.');
}

function isUnspecifiedHost(host) {
  const h = String(host || '').trim().toLowerCase().replace(/^\[|\]$/g, '');
  return !h || h === '0.0.0.0' || h === '::' || h === '*' || h === '::ffff:0.0.0.0';
}

function parseEnvProxyPorts() {
  const ports = new Set();
  for (const key of ['HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'http_proxy', 'https_proxy', 'all_proxy']) {
    const val = process.env[key];
    if (!val) continue;
    for (const m of String(val).matchAll(/:(\d{2,5})\b/g)) {
      const p = Number(m[1]);
      if (p > 0 && p <= 65535) ports.add(p);
    }
  }
  return ports;
}

function toLocalDateKey(tsMs) {
  const d = new Date(tsMs);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function atomicWriteJson(filePath, data) {
  mkdirSync(dirname(filePath), { recursive: true });
  const payload = JSON.stringify(data);
  const tmp = `${filePath}.${process.pid}.tmp`;
  try {
    writeFileSync(tmp, payload, 'utf8');
    renameSync(tmp, filePath);
  } catch {
    try {
      rmSync(tmp, { force: true });
    } catch {}
    writeFileSync(filePath, payload, 'utf8');
  }
}

export function createEmptyTrafficDay() {
  return {
    upBytes: 0,
    downBytes: 0,
    hourlyUp: new Array(24).fill(0),
    hourlyDown: new Array(24).fill(0),
  };
}

function sanitizeHourlyArray(arr) {
  const out = new Array(24).fill(0);
  if (!Array.isArray(arr)) return out;
  for (let i = 0; i < 24; i++) {
    const v = Number(arr[i] || 0);
    out[i] = Number.isFinite(v) && v > 0 ? Math.round(v) : 0;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Cross-platform parsers (exported for unit tests)
// ---------------------------------------------------------------------------

function splitHostPort(endpoint) {
  const raw = String(endpoint || '').trim();
  if (!raw) return { host: '', port: 0 };
  const bracket = raw.match(/^\[([^\]]+)\]:(\d+)$/);
  if (bracket) return { host: bracket[1], port: Number(bracket[2]) };
  const lastColon = raw.lastIndexOf(':');
  if (lastColon > 0) {
    const port = Number(raw.slice(lastColon + 1));
    if (Number.isFinite(port)) {
      return { host: raw.slice(0, lastColon), port };
    }
  }
  const lastDot = raw.lastIndexOf('.');
  if (lastDot > 0) {
    const port = Number(raw.slice(lastDot + 1));
    if (Number.isFinite(port)) {
      return { host: raw.slice(0, lastDot), port };
    }
  }
  return { host: raw, port: 0 };
}

/**
 * Parse Linux `ss -tlpnH` + `ss -tinpH` outputs into per-connection byte snapshots.
 */
export function parseLinuxSsOutput(tcpText, listenText = '', configuredProxyPorts = new Set()) {
  const agyListenPorts = new Set();
  const proxyListenPorts = new Set(configuredProxyPorts);

  for (const line of String(listenText || '').split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const cols = trimmed.split(/\s+/);
    if (cols.length < 5) continue;
    const local = splitHostPort(cols[3]);
    if (!local.port) continue;
    for (const m of trimmed.matchAll(/\("([^"]+)",pid=(\d+)/g)) {
      const proc = m[1];
      if (isAntigravityProcessName(proc)) agyListenPorts.add(local.port);
      if (isKnownProxyProcessName(proc)) proxyListenPorts.add(local.port);
    }
  }

  const lines = String(tcpText || '').split(/\r?\n/);
  const parsedSockets = [];
  let current = null;

  for (const rawLine of lines) {
    if (!rawLine.trim()) continue;
    if (!/^\s/.test(rawLine)) {
      const cols = rawLine.trim().split(/\s+/);
      if (cols.length < 5) {
        current = null;
        continue;
      }
      const state = cols[0];
      const local = splitHostPort(cols[3]);
      const remote = splitHostPort(cols[4]);
      const procMatch = rawLine.match(/\("([^"]+)",pid=(\d+)/);
      const proc = procMatch ? procMatch[1] : '';
      const pid = procMatch ? Number(procMatch[2]) : 0;

      current = { state, local, remote, proc, pid, sent: 0, recv: 0 };
      parsedSockets.push(current);
    } else if (current) {
      const sentM = rawLine.match(/\bbytes_sent:(\d+)/);
      const recvM = rawLine.match(/\bbytes_received:(\d+)/);
      if (sentM) current.sent = Number(sentM[1]);
      if (recvM) current.recv = Number(recvM[1]);
    }
  }

  const conns = new Map();
  const agyPids = new Set();

  for (const s of parsedSockets) {
    if (!isAntigravityProcessName(s.proc) || !s.pid) continue;
    agyPids.add(s.pid);
    if (!['ESTAB', 'FIN-WAIT-1', 'FIN-WAIT-2', 'CLOSE-WAIT', 'CLOSING', 'LAST-ACK'].includes(s.state)) {
      continue;
    }
    if (isUnspecifiedHost(s.remote.host) || !s.remote.port) continue;

    if (isLoopbackHost(s.remote.host)) {
      if (agyListenPorts.has(s.local.port) || agyListenPorts.has(s.remote.port)) continue;
      if (!proxyListenPorts.has(s.remote.port)) continue;
    }

    const key = `tcp:${s.pid}:${s.local.host}:${s.local.port}->${s.remote.host}:${s.remote.port}`;
    conns.set(key, { outBytes: s.sent, inBytes: s.recv });
  }

  return { conns, pidCount: agyPids.size };
}

/**
 * Parse macOS `lsof -nP -iTCP -sTCP:LISTEN` + `nettop -L 1 -m tcp -J bytes_in,bytes_out -x`.
 */
export function parseMacNettopOutput(nettopText, lsofListenText = '', configuredProxyPorts = new Set()) {
  const agyListenPorts = new Set();
  const proxyListenPorts = new Set(configuredProxyPorts);

  for (const line of String(lsofListenText || '').split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('COMMAND')) continue;
    const cols = trimmed.split(/\s+/);
    if (cols.length < 9) continue;
    const proc = cols[0];
    const nameField = cols[cols.length - 1] === '(LISTEN)' ? cols[cols.length - 2] : cols[cols.length - 1];
    const ep = splitHostPort(nameField.replace(/\(LISTEN\)$/i, '').trim());
    if (!ep.port) continue;
    if (isAntigravityProcessName(proc)) agyListenPorts.add(ep.port);
    if (isKnownProxyProcessName(proc)) proxyListenPorts.add(ep.port);
  }

  const conns = new Map();
  const agyPids = new Set();
  let curProc = '';
  let curPid = 0;
  let curIsAgy = false;

  for (const rawLine of String(nettopText || '').split(/\r?\n/)) {
    if (!rawLine.trim()) continue;
    const parts = rawLine.split(',');
    if (parts.length < 3) continue;

    const col0 = parts[0].trim();
    const col1 = parts[1].trim();
    if (/^bytes_in$/i.test(col1) || /^bytes_in$/i.test(parts[2]?.trim() || '')) continue;

    const hasTimeCol = /^\d{2}:\d{2}:\d{2}/.test(col0);
    const labelCol = hasTimeCol ? parts[1] : parts[0];
    const inCol = hasTimeCol ? parts[2] : parts[1];
    const outCol = hasTimeCol ? parts[3] : parts[2];

    const labelTrim = String(labelCol || '').trim();
    if (!labelTrim) continue;

    const sockMatch = labelTrim.match(/^(tcp[46]?)\s+(\S+)<->(\S+)$/i);
    if (!sockMatch) {
      const procMatch = labelTrim.match(/^(.+)\.(\d+)$/);
      if (procMatch) {
        curProc = procMatch[1].trim();
        curPid = Number(procMatch[2]);
        curIsAgy = isAntigravityProcessName(curProc);
        if (curIsAgy && curPid > 0) agyPids.add(curPid);
      }
      continue;
    }

    if (!curIsAgy || !curPid) continue;
    const proto = sockMatch[1].toLowerCase();
    const local = splitHostPort(sockMatch[2]);
    const remote = splitHostPort(sockMatch[3]);
    const inBytes = Math.max(0, Number(inCol || 0));
    const outBytes = Math.max(0, Number(outCol || 0));

    if (!Number.isFinite(inBytes) || !Number.isFinite(outBytes)) continue;
    if (isUnspecifiedHost(remote.host) || !remote.port) continue;

    if (isLoopbackHost(remote.host)) {
      if (agyListenPorts.has(local.port) || agyListenPorts.has(remote.port)) continue;
      if (!proxyListenPorts.has(remote.port)) continue;
    }

    const key = `${proto}:${curPid}:${local.host}:${local.port}->${remote.host}:${remote.port}`;
    conns.set(key, { outBytes, inBytes });
  }

  return { conns, pidCount: agyPids.size };
}

export function parseWindowsWorkerMessage(msg) {
  const validStates = new Set(['active', 'admin_required', 'unavailable', 'starting', 'idle']);
  const rawState = typeof msg?.status === 'string' ? msg.status : '';
  const state = validStates.has(rawState) ? rawState : 'unavailable';
  const activeConns = Math.max(0, Math.round(Number(msg?.activeConns || 0)) || 0);
  const pidCount = Math.max(0, Math.round(Number(msg?.pidCount || 0)) || 0);
  const upDelta = state === 'active' ? Number(msg?.upDelta ?? 0) : 0;
  const downDelta = state === 'active' ? Number(msg?.downDelta ?? 0) : 0;
  const error =
    state === 'admin_required'
      ? 'Administrator privileges required on Windows'
      : state === 'unavailable'
        ? String(msg?.error || 'Windows traffic worker unavailable')
        : '';
  return { state, activeConns, pidCount, upDelta, downDelta, error };
}

export function createProxyTrafficSampler() {
  let previous = new Map();
  let previousAt = null;
  return (connections, sampledAt) => {
    const current = new Map();
    let upDelta = 0;
    let downDelta = 0;
    for (const row of connections) {
      const name = String(row?.metadata?.processPath || row?.metadata?.process || '').split(/[\\/]/).pop();
      if (!/^(antigravity|language_server)\.exe$/i.test(name)) continue;
      const { id, start, upload, download } = row;
      if (typeof id !== 'string' || !id || !Number.isSafeInteger(upload) || upload < 0 ||
          !Number.isSafeInteger(download) || download < 0) continue;
      const key = JSON.stringify([id, start]);
      if (current.has(key)) continue;
      const old = previous.get(key);
      const openedAt = Date.parse(start);
      const openedSinceSample = previousAt !== null && openedAt >= previousAt && openedAt <= sampledAt;
      if (old) {
        upDelta += Math.max(0, upload - old.upload);
        downDelta += Math.max(0, download - old.download);
      } else if (openedSinceSample) {
        upDelta += upload;
        downDelta += download;
      }
      current.set(key, { upload, download });
    }
    previous = current;
    previousAt = sampledAt;
    return { upDelta, downDelta, activeConns: current.size };
  };
}

// ---------------------------------------------------------------------------
// Traffic archive + cross-platform monitor service
// ---------------------------------------------------------------------------

export function createTrafficMonitor(options = {}) {
  const stateDir = options.stateDir;
  const useProxy = process.platform === 'win32' && process.env.AGY_LEDGER_WINDOWS_TRAFFIC !== 'estats';
  const archivePath = join(stateDir, useProxy ? 'proxy-traffic-archive.json' : 'traffic-archive.json');
  const nowFn = options.nowFn || (() => Date.now());
  const disableArchiveWrite = Boolean(options.disableArchiveWrite);
  const onDelta = typeof options.onDelta === 'function' ? options.onDelta : () => {};

  const daysMap = new Map(); // dateKey -> { upBytes, downBytes, hourlyUp[24], hourlyDown[24] }
  let loaded = false;
  let dirty = false;
  let lastFlushAt = 0;
  let started = false;
  let stopped = false;

  let winChild = null;
  let winRestartTimer = null;
  let unixTimer = null;
  let unixBusy = false;
  let unixBaselineDone = false;
  let unixPrevByConn = new Map();
  let cachedListenText = '';
  let lastListenRefreshAt = 0;
  let proxyPort = 0;
  let configuredPort;
  let nextDiscoveryAt = 0;
  let sampleProxy = createProxyTrafficSampler();

  const backendName =
    process.platform === 'win32'
      ? (useProxy ? 'win-proxy' : 'win-estats')
      : process.platform === 'darwin'
        ? 'macos-nettop'
        : process.platform === 'linux'
          ? 'linux-ss'
          : 'unsupported';

  let status = {
    state: 'idle', // 'idle' | 'starting' | 'active' | 'admin_required' | 'unavailable'
    backend: backendName,
    activeConns: 0,
    pidCount: 0,
    lastSampleAt: 0,
    error: '',
  };

  function loadIfNeeded() {
    if (loaded) return;
    loaded = true;
    try {
      if (!existsSync(archivePath)) return;
      const raw = JSON.parse(readFileSync(archivePath, 'utf8'));
      const rawDays = raw?.days;
      if (rawDays && typeof rawDays === 'object') {
        for (const [dateKey, entry] of Object.entries(rawDays)) {
          if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey) || !entry || typeof entry !== 'object') continue;
          const upBytes = Math.max(0, Math.round(Number(entry.upBytes || 0)));
          const downBytes = Math.max(0, Math.round(Number(entry.downBytes || 0)));
          const hourlyUp = sanitizeHourlyArray(entry.hourlyUp);
          const hourlyDown = sanitizeHourlyArray(entry.hourlyDown);
          daysMap.set(dateKey, { upBytes, downBytes, hourlyUp, hourlyDown });
        }
      }
    } catch {}
  }

  function flush(force = false) {
    if (disableArchiveWrite || !dirty) return;
    const now = nowFn();
    if (!force && now - lastFlushAt < FLUSH_INTERVAL_MS) return;
    try {
      const days = {};
      for (const [dateKey, entry] of daysMap.entries()) {
        if (entry.upBytes <= 0 && entry.downBytes <= 0) continue;
        days[dateKey] = {
          upBytes: entry.upBytes,
          downBytes: entry.downBytes,
          hourlyUp: entry.hourlyUp,
          hourlyDown: entry.hourlyDown,
        };
      }
      atomicWriteJson(archivePath, {
        version: 1,
        updatedAt: now,
        days,
      });
      dirty = false;
      lastFlushAt = now;
    } catch {}
  }

  function recordDelta(upDelta, downDelta, tsMs = nowFn()) {
    loadIfNeeded();
    const u = Number(upDelta ?? 0);
    const d = Number(downDelta ?? 0);
    if (!Number.isFinite(u) || !Number.isFinite(d)) return false;
    if (u < 0 || d < 0) return false;
    if (u === 0 && d === 0) return false;
    if (u > MAX_SINGLE_TICK_BYTES || d > MAX_SINGLE_TICK_BYTES) return false;

    const safeU = Math.round(u);
    const safeD = Math.round(d);
    if (safeU === 0 && safeD === 0) return false;

    const dt = new Date(tsMs);
    const dateKey = toLocalDateKey(tsMs);
    const hour = dt.getHours();

    let day = daysMap.get(dateKey);
    if (!day) {
      day = createEmptyTrafficDay();
      daysMap.set(dateKey, day);
    }
    day.upBytes += safeU;
    day.downBytes += safeD;
    day.hourlyUp[hour] += safeU;
    day.hourlyDown[hour] += safeD;

    dirty = true;
    flush(false);
    onDelta({ upDelta: safeU, downDelta: safeD, dateKey });
    return true;
  }

  function applyConnSnapshot(conns, pidCount) {
    let upDelta = 0;
    let downDelta = 0;
    const seen = new Set();

    for (const [key, cur] of conns.entries()) {
      seen.add(key);
      const prev = unixPrevByConn.get(key);
      if (prev) {
        const dOut = cur.outBytes >= prev.outBytes ? cur.outBytes - prev.outBytes : 0;
        const dIn = cur.inBytes >= prev.inBytes ? cur.inBytes - prev.inBytes : 0;
        if (dOut <= MAX_SINGLE_TICK_BYTES) upDelta += dOut;
        if (dIn <= MAX_SINGLE_TICK_BYTES) downDelta += dIn;
      } else if (unixBaselineDone) {
        if (cur.outBytes <= MAX_SINGLE_TICK_BYTES) upDelta += cur.outBytes;
        if (cur.inBytes <= MAX_SINGLE_TICK_BYTES) downDelta += cur.inBytes;
      }
      unixPrevByConn.set(key, { outBytes: cur.outBytes, inBytes: cur.inBytes });
    }

    for (const k of [...unixPrevByConn.keys()]) {
      if (!seen.has(k)) unixPrevByConn.delete(k);
    }

    unixBaselineDone = true;
    status = {
      ...status,
      state: 'active',
      activeConns: conns.size,
      pidCount,
      lastSampleAt: nowFn(),
      error: '',
    };

    if (upDelta > 0 || downDelta > 0) {
      recordDelta(upDelta, downDelta);
    }
  }

  function startWindowsWorker() {
    if (stopped || winChild) return;
    if (!existsSync(WIN_MONITOR_SCRIPT)) {
      status = { ...status, state: 'unavailable', error: 'win_tcp_monitor.ps1 missing' };
      return;
    }
    status = { ...status, state: 'starting', error: '' };
    const psExe = join(
      process.env.SystemRoot || 'C:\\Windows',
      'System32',
      'WindowsPowerShell',
      'v1.0',
      'powershell.exe'
    );

    let child;
    try {
      child = spawn(
        psExe,
        [
          '-NoProfile',
          '-NonInteractive',
          '-WindowStyle',
          'Hidden',
          '-ExecutionPolicy',
          'Bypass',
          '-File',
          WIN_MONITOR_SCRIPT,
          '-ParentPid',
          String(process.pid),
          '-PollMs',
          String(WIN_POLL_MS),
        ],
        {
          stdio: ['pipe', 'pipe', 'pipe'],
          windowsHide: true,
        }
      );
    } catch (err) {
      status = { ...status, state: 'unavailable', error: err?.message || 'spawn failed' };
      return;
    }

    winChild = child;
    let buf = '';
    let errBuf = '';

    child.stdout.setEncoding('utf8');
    child.stdout.on('data', (chunk) => {
      buf += chunk;
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith('{')) continue;
        try {
          const msg = JSON.parse(line);
          const parsed = parseWindowsWorkerMessage(msg);
          const prevState = status.state;
          status = {
            ...status,
            state: parsed.state,
            activeConns: parsed.activeConns,
            pidCount: parsed.pidCount,
            lastSampleAt: nowFn(),
            error: parsed.error,
          };
          const recorded =
            parsed.state === 'active' ? recordDelta(parsed.upDelta, parsed.downDelta) : false;
          if (!recorded && prevState !== status.state) {
            onDelta({ upDelta: 0, downDelta: 0, statusChanged: true });
          }
        } catch {}
      }
    });

    child.stderr.setEncoding('utf8');
    child.stderr.on('data', (chunk) => {
      errBuf = (errBuf + chunk).slice(-400);
    });

    child.on('exit', () => {
      if (winChild === child) winChild = null;
      if (stopped) return;
      if (status.state !== 'admin_required') {
        status = { ...status, state: 'unavailable', error: errBuf.trim() || 'worker exited' };
      }
      winRestartTimer = setTimeout(() => {
        winRestartTimer = null;
        if (!stopped) startWindowsWorker();
      }, 15_000);
      winRestartTimer.unref?.();
    });
  }

  async function pollMacOnce() {
    const now = nowFn();
    if (now - lastListenRefreshAt > 15_000) {
      try {
        const { stdout } = await execFileAsync('lsof', ['-nP', '-iTCP', '-sTCP:LISTEN'], {
          timeout: 2500,
          maxBuffer: 4 * 1024 * 1024,
        });
        cachedListenText = stdout;
        lastListenRefreshAt = now;
      } catch {}
    }
    const { stdout } = await execFileAsync(
      '/usr/bin/nettop',
      ['-L', '1', '-m', 'tcp', '-J', 'bytes_in,bytes_out', '-x'],
      { timeout: 2800, maxBuffer: 8 * 1024 * 1024 }
    );
    const { conns, pidCount } = parseMacNettopOutput(stdout, cachedListenText, parseEnvProxyPorts());
    applyConnSnapshot(conns, pidCount);
  }

  async function pollLinuxOnce() {
    const now = nowFn();
    if (now - lastListenRefreshAt > 15_000) {
      try {
        const { stdout } = await execFileAsync('ss', ['-tlpnH'], {
          timeout: 2000,
          maxBuffer: 4 * 1024 * 1024,
        });
        cachedListenText = stdout;
        lastListenRefreshAt = now;
      } catch {}
    }
    const { stdout } = await execFileAsync('ss', ['-tinpH'], {
      timeout: 2000,
      maxBuffer: 8 * 1024 * 1024,
    });
    const { conns, pidCount } = parseLinuxSsOutput(stdout, cachedListenText, parseEnvProxyPorts());
    applyConnSnapshot(conns, pidCount);
  }

  async function controllerGet(port, path) {
    const token = configuredPort === port ? process.env.AGY_LEDGER_PROXY_TOKEN : '';
    const response = await fetch(`http://127.0.0.1:${port}${path}`, {
      signal: AbortSignal.timeout(900),
      redirect: 'error',
      headers: token ? { Authorization: `Bearer ${token}` } : undefined,
    });
    if (!response.ok) throw new Error(`Proxy controller HTTP ${response.status}`);
    return response.json();
  }

  async function discoverController(ports) {
    const candidates = await Promise.allSettled(ports.map(async (port) => {
      const info = await controllerGet(port, '/version');
      if (typeof info?.version !== 'string' || !info.version) throw new Error('Invalid controller version');
      const data = await controllerGet(port, '/connections');
      if (!Array.isArray(data?.connections) &&
          !(data?.connections === null && Number.isSafeInteger(data.uploadTotal))) {
        throw new Error('Connection API unavailable');
      }
      return port;
    }));
    return candidates.find((candidate) => candidate.status === 'fulfilled')?.value;
  }

  async function findWindowsControllerPorts() {
    const opts = { timeout: 2500, windowsHide: true };
    const [{ stdout: processes }, { stdout: sockets }] = await Promise.all([
      execFileAsync('tasklist.exe', ['/FO', 'CSV', '/NH'], opts),
      execFileAsync('netstat.exe', ['-ano', '-p', 'TCP'], opts),
    ]);
    const pids = new Set();
    for (const line of processes.split(/\r?\n/)) {
      const match = line.match(/^"(?:sing-box|mihomo|verge-mihomo(?:-alpha)?|clash(?:-meta|-premium|-win64)?)\.exe"\s*,\s*"(\d+)"/i);
      if (match) pids.add(match[1]);
    }
    const ports = new Set();
    for (const line of sockets.split(/\r?\n/)) {
      const match = line.match(/^\s*TCP\s+(?:127\.0\.0\.1|0\.0\.0\.0):(\d+)\s+0\.0\.0\.0:0\s+\S+\s+(\d+)\s*$/i);
      if (match && pids.has(match[2])) ports.add(Number(match[1]));
    }
    return [...ports].filter((port) => !LOCAL_CONTROLLER_PORTS.includes(port)).slice(0, 12);
  }

  async function pollProxyOnce() {
    const override = options.getProxyControllerPort?.() || 0;
    if (configuredPort !== override) {
      configuredPort = override;
      proxyPort = 0;
      nextDiscoveryAt = 0;
      sampleProxy = createProxyTrafficSampler();
    }
    try {
      if (!proxyPort) {
        if (nowFn() < nextDiscoveryAt) return;
        let found = await discoverController(override ? [override] : LOCAL_CONTROLLER_PORTS);
        if (!found && !override && !stopped) {
          found = await discoverController(await findWindowsControllerPorts());
        }
        if (stopped) return;
        if (!found) throw new Error('Local proxy controller is unavailable');
        proxyPort = found;
      }
      const sampledAt = nowFn();
      const data = await controllerGet(proxyPort, '/connections');
      if (stopped || (options.getProxyControllerPort?.() || 0) !== override) return;
      const rows = data?.connections === null && Number.isSafeInteger(data.uploadTotal) ? [] : data?.connections;
      if (!Array.isArray(rows)) throw new Error('Connection API unavailable');
      if (rows.length && !rows.some((row) => row?.metadata?.processPath || row?.metadata?.process)) {
        throw new Error('Proxy did not provide process names');
      }
      const { upDelta, downDelta, activeConns } = sampleProxy(rows, sampledAt);
      const changed = status.state !== 'active' || status.activeConns !== activeConns || status.controllerPort !== proxyPort;
      status = { ...status, state: 'active', activeConns, controllerPort: proxyPort, lastSampleAt: sampledAt, error: '' };
      if (!recordDelta(upDelta, downDelta, sampledAt) && changed) onDelta({ statusChanged: true });
    } catch (err) {
      if (stopped) return;
      const changed = status.state !== 'unavailable' || status.error !== err?.message;
      status = {
        ...status, state: 'unavailable', activeConns: 0, controllerPort: proxyPort || override,
        error: err?.message || 'Proxy connection sample failed',
      };
      proxyPort = 0;
      sampleProxy = createProxyTrafficSampler();
      nextDiscoveryAt = nowFn() + 5000;
      if (changed) onDelta({ statusChanged: true });
    }
  }

  function startPoller(pollFn, intervalMs) {
    status = { ...status, state: 'starting', error: '' };
    const run = async () => {
      if (stopped || unixBusy) return;
      unixBusy = true;
      try {
        await pollFn();
      } catch (err) {
        status = { ...status, state: 'unavailable', error: err?.message || 'poll failed' };
      } finally {
        unixBusy = false;
      }
    };
    run();
    unixTimer = setInterval(run, intervalMs);
    unixTimer.unref?.();
  }

  function start() {
    loadIfNeeded();
    if (started || stopped) return;
    started = true;

    if (useProxy) {
      startPoller(pollProxyOnce, PROXY_POLL_MS);
    } else if (process.platform === 'win32') {
      startWindowsWorker();
    } else if (process.platform === 'darwin') {
      startPoller(pollMacOnce, MAC_POLL_MS);
    } else if (process.platform === 'linux') {
      startPoller(pollLinuxOnce, LINUX_POLL_MS);
    } else {
      status = { ...status, state: 'unavailable', error: `Unsupported platform: ${process.platform}` };
    }
  }

  function stop() {
    stopped = true;
    if (winRestartTimer) {
      clearTimeout(winRestartTimer);
      winRestartTimer = null;
    }
    if (unixTimer) {
      clearInterval(unixTimer);
      unixTimer = null;
    }
    if (winChild) {
      const child = winChild;
      winChild = null;
      try {
        child.stdin?.end();
      } catch {}
      try {
        child.kill();
      } catch {}
    }
    flush(true);
  }

  function getDaysMap() {
    loadIfNeeded();
    return daysMap;
  }

  function getStatus() {
    return { ...status };
  }

  return {
    archivePath,
    start,
    stop,
    flush,
    recordDelta,
    getDaysMap,
    getStatus,
  };
}
